window.AUTH=window.AUTH||{};window.AUTH["21-1170"]={"d":"21-1170","id":"2022/21-1170","n":"Ciminelli v. United States","briefs":[{"k":"petitioner","label":"Brief of petitioner Louis Ciminelli","date":"2022-08-29","url":"https://www.supremecourt.gov/DocketPDF/21/21-1170/236600/20220829154502902_Ciminelli%20Petitioner%20Brief%20-%20For%20E%20File.pdf","side":"pet","n":65},{"k":"respondent","label":"Brief of respondent Alain Kaloyeros in support of petitioner","date":"2022-08-29","url":"https://www.supremecourt.gov/DocketPDF/21/21-1170/236619/20220829181043374_No.%2021-1170_Brief%20for%20Respondent%20Alain%20Kaloyeros%20in%20Support%20of%20Petitioner.pdf","side":"res","n":44},{"k":"respondent","label":"Brief of respondents Steven Aiello and Joseph Gerardi in support of petitioner","date":"2022-08-29","url":"https://www.supremecourt.gov/DocketPDF/21/21-1170/236565/20220829124731210_Ciminelli%20v.%20US%20%208.29.22.pdfA.pdf","side":"res","n":44},{"k":"respondent","label":"Brief of respondent United States","date":"2022-10-12","url":"https://www.supremecourt.gov/DocketPDF/21/21-1170/243007/20221012202656269_21-1170bsUnitedStates%20FINAL.pdf","side":"res","n":38},{"k":"reply","label":"Reply of petitioner Louis Ciminelli","date":"2022-11-14","url":"https://www.supremecourt.gov/DocketPDF/21/21-1170/246432/20221114161111801_Ciminelli%20Reply%20Brief.pdf","side":"pet","n":44}],"opinion":"https://www.supremecourt.gov/opinions/22pdf/598us2r15_d1o2.pdf","tr":true,"items":[{"t":"case","label":"Ala. Ass’n of Realtors v. Dep’t of Health & Hum. Serv.","cite":"141 S. Ct. 2485","y":2021,"url":"https://www.courtlistener.com/c/S.%20Ct./141/2485/","sc":1,"by":{"0":"21"}},{"t":"case","label":"Bousley v. United States","cite":"523 U.S. 614","y":1998,"id":"1997/96-8516","sc":1,"by":{"0":"18","1":"19"},"q":[{"src":"brief","b":0,"text":"[f]or under our federal system it is only Congress, and not the courts, which can make conduct criminal.","cite":"523 U.S. 614, 620-21"},{"src":"brief","b":1,"text":"[U]nder our federal system it is only Congress, and not the courts, which can make conduct criminal.","cite":"523 U.S. 614, 620-21"}]},{"t":"case","label":"Boyle v. United States","cite":"556 U.S. 938","y":2009,"id":"2008/07-1309","sc":1,"by":{"0":"41"}},{"t":"case","label":"Carpenter v. United States","cite":"484 U.S. 19","y":1987,"id":"1987/86-422","sc":1,"by":{"0":"passim","1":"12","2":"16","3":"16, 17, 20, 22","4":"11"},"q":[{"src":"brief","b":0,"text":"share the same language in relevant part.","cite":"484 U.S. at 25 n.6"},{"src":"opinion","who":"Opinion of the Court (Justice Thomas)","text":"has long been recognized as property,","cite":"484 U. S. 19, 26"},{"src":"argument","who":"Mr. Dreeben","text":"I think they all cumulatively reinforce each other, and the Court may wish to take this opportunity to say what it has already said in Cleveland and in Carpenter, which is that the wire fraud and mail fraud statutes protect traditional property interests."},{"src":"argument","who":"Mr. Feigin","text":"It pointed to Carpenter as an example of not requiring harm, and Carpenter is a case in which the victim, The Wall Street Journal, wasn't economically harmed at all."}]},{"t":"case","label":"Cedar Point Nursery v. Hassid","cite":"141 S. Ct. 2063","y":2021,"id":"2020/20-107","sc":1,"by":{"0":"21","2":"30"},"q":[{"src":"brief","b":0,"text":"The right to exclude is ‘one of the most treasured’ rights of property ownership.","cite":"141 S. Ct. 2063, 2073"}]},{"t":"case","label":"Cleveland v. United States","cite":"531 U.S. 12","y":2000,"id":"2000/99-804","sc":1,"by":{"0":"passim","1":"1, 15, 20, 22","2":"17, 19","3":"16, 33, 46","4":"11, 16, 24"},"q":[{"src":"brief","b":0,"text":"Significantly, Congress covered only the intangible right of honest services,","cite":"531 U.S. at 20"},{"src":"brief","b":1,"text":"a new statute ‘specifically to cover one of the ‘intangible rights’ that lower courts had protected ... prior to McNally: ‘the intangible right of honest services.’","cite":"531 U.S. at 19"},{"src":"brief","b":3,"text":"a wide range of conduct traditionally regulated by state and local authorities.","cite":"531 U.S. at 24"},{"src":"opinion","who":"Opinion of the Court (Justice Thomas)","text":"specifcally to cover one of the `intangible rights' that lower courts had protected under [the statutes] prior to McNally: `the intangible right of honest services.'","cite":"531 U. S., at 19"},{"src":"opinion","who":"Opinion of the Court (Justice Thomas)","text":"stray from traditional concepts of property.","cite":"531 U. S., at 24"},{"src":"opinion","who":"Opinion of the Court (Justice Thomas)","text":"only the intangible right of honest services.","cite":"531 U. S., at 19"},{"src":"argument","who":"Mr. Dreeben","text":"I think they all cumulatively reinforce each other, and the Court may wish to take this opportunity to say what it has already said in Cleveland and in Carpenter, which is that the wire fraud and mail fraud statutes protect traditional property interests."},{"src":"argument","who":"Mr. Feigin","text":"And the -- this Court nodded to the idea of a right-to-control theory, admittedly, without endorsing it, in both McNally and Cleveland. And I think the Second Circuit had a defensible way of doing this at -- at the beginning, but it's become clear that it's an awkward fit with property fraud as it's been traditionally understood."}]},{"t":"case","label":"Coll. Sav. Bank v. Fla. Prepaid Postsecondary Educ. Expense Bd.","cite":"527 U.S. 666","y":1999,"id":"1998/98-149","sc":1,"by":{"0":"30"},"q":[{"src":"brief","b":0,"text":"[N]ot everything which protects property interests is designed to remedy or prevent deprivations of those property interests.","cite":"527 U.S. 666, 674"}]},{"t":"case","label":"Dickman v. Commissioner","cite":"465 U.S. 330","y":1984,"id":"1983/82-1041","sc":1,"by":{"0":"42, 43"}},{"t":"case","label":"Durland v. United States","cite":"161 U.S. 306","y":1896,"id":"scdb/1895-139","sc":1,"by":{"0":"19, 31","1":"22","3":"40","4":"12"},"q":[{"src":"brief","b":0,"text":"any scheme or artifice to defraud","cite":"161 U.S. 306"}]},{"t":"case","label":"Elston v. Schilling","cite":"42 N.Y. 79","y":1870,"url":"https://www.courtlistener.com/c/N.Y./42/79/","by":{"0":"23"}},{"t":"case","label":"Fasulo v. United States","cite":"272 U.S. 620","y":1926,"id":"scdb/1926-024","sc":1,"by":{"0":"19, 26"},"q":[{"src":"brief","b":0,"text":"There are no constructive offenses; and before one can be punished, it must be shown that his case is plainly within the statute.","cite":"272 U.S. 620, 629"}]},{"t":"case","label":"Fresh Pond Shopping Ctr., Inc. v. Callahan","cite":"464 U.S. 875","y":1983,"url":"https://supreme.justia.com/cases/federal/us/464/875/","sc":1,"by":{"0":"21"}},{"t":"case","label":"Hammerschmidt v. United States","cite":"265 U.S. 182","y":1924,"id":"scdb/1923-145","sc":1,"by":{"0":"34","1":"22","4":"10"},"q":[{"src":"brief","b":0,"text":"commonly refer[s] to wronging one in his property rights by dishonest methods or schemes,","cite":"265 U.S. 182, 188"}]},{"t":"case","label":"Johnson v. United States","cite":"576 U.S. 591","y":2015,"id":"2014/13-7120","sc":1,"by":{"0":"41, 47"}},{"t":"case","label":"Jones v. United States","cite":"529 U.S. 848","y":2000,"id":"1999/99-5739","sc":1,"by":{"0":"41","1":"20"}},{"t":"case","label":"Kansas v. Garcia","cite":"140 S. Ct. 791","y":2020,"id":"2019/17-834","sc":1,"by":{"0":"47"},"q":[{"src":"brief","b":0,"text":"From the beginning of our country, criminal law enforcement has been primarily a responsibility of the States, and that remains true today.","cite":"140 S. Ct. 791, 806"}]},{"t":"case","label":"Kelly v. United States","cite":"140 S. Ct. 1565","y":2020,"id":"2019/18-1059","sc":1,"by":{"0":"passim","1":"1, 13, 20, 33","2":"3, 16, 17, 29","3":"16, 32","4":"10, 11, 24"},"q":[{"src":"brief","b":0,"text":"engaged in deception, but [also] that an object of the[] fraud was [money or] property.","cite":"140 S. Ct. at 1571"},{"src":"brief","b":0,"text":"aim to obtain money or property.","cite":"140 S. Ct. at 1574"},{"src":"brief","b":1,"text":"that ‘the money-or-property requirement of the latter phrase’ also limits the former.","cite":"140 S. Ct. at 1571"},{"src":"brief","b":2,"text":"the ‘object’ of obtaining the [victim’s] money or property.","cite":"140 S. Ct. 1565, 1572"},{"src":"brief","b":2,"text":"the deceit must also have had the ‘object’ of obtaining the [victim’s] money or property.","cite":"140 S. Ct. at 1572"},{"src":"brief","b":3,"text":"disjunctive language as a unitary whole,","cite":"140 S. Ct. 1565, 1571"},{"src":"brief","b":3,"text":"must be an ‘object of the fraud.’","cite":"140 S. Ct. at 1573"},{"src":"brief","b":4,"text":"to enforce (its view of) integrity.","cite":"140 S. Ct. at 1568, 1574"}]},{"t":"case","label":"Loretto v. Teleprompter Manhattan CATV Corp.","cite":"458 U.S. 419","y":1982,"id":"1981/81-244","sc":1,"by":{"0":"21, 23"}},{"t":"case","label":"McDonnell v. United States","cite":"579 U.S. 550","y":2016,"id":"2015/15-474","sc":1,"by":{"0":"46, 47","1":"20","4":"16"},"q":[{"src":"brief","b":4,"text":"cannot construe a criminal statute on the assumption that the Government will use it responsibly.","cite":"579 U.S. 550, 576"}]},{"t":"case","label":"McKeon v. Bisbee","cite":"9 Cal. 137","y":1858,"url":"https://www.courtlistener.com/c/Cal./9/137/","by":{"0":"20"}},{"t":"case","label":"McNally v. United States","cite":"483 U.S. 350","y":1987,"id":"1986/86-234","sc":1,"by":{"0":"passim","1":"passim","2":"17, 33","3":"16, 46","4":"10, 11, 20"},"q":[{"src":"brief","b":0,"text":"it must speak more clearly than it has.","cite":"483 U.S. at 360"},{"src":"brief","b":0,"text":"or for obtaining money or property by means of false or fraudulent pretenses, representations, or promises.","cite":"483 U.S. at 356"},{"src":"brief","b":1,"text":"‘If Congress desires to go further, it must speak more clearly than it has.’","cite":"483 U.S. at 360"},{"src":"brief","b":1,"text":"construe the statute in a manner that leaves its outer boundaries ambiguous and involves the Federal Government in setting standards of disclosure and good government for local and state officials.","cite":"483 U.S. at 360"},{"src":"brief","b":2,"text":"If Congress desires to go further, it must speak more clearly than it has.","cite":"483 U.S. at 360"},{"src":"brief","b":4,"text":"it must speak more clearly than it has.","cite":"483 U.S. at 360"},{"src":"opinion","who":"Opinion of the Court (Justice Thomas)","text":"limited in scope to the protection of property rights.","cite":"483 U. S., at 360"},{"src":"opinion","who":"Opinion of the Court (Justice Thomas)","text":"in a manner that leaves [their] outer boundaries ambiguous.","cite":"483 U. S. 350, 360"},{"src":"argument","who":"Mr. Dreeben","text":"Well, Justice Barrett, the reason why I don't think that it's an appropriate issue for the Second Circuit to get on remand is this Court's repeated statements in cases like Dunn, McCormick, and specifically Chiarella and McNally itself that the Court cannot affirm a criminal conviction on the basis of a theory not presented to the jury."},{"src":"argument","who":"Mr. Dreeben","text":"And this Court in McNally said: It protected against being wronged in your property rights. And it didn't mean conventional fraudulent inducement, which is grist for the mill in a thousand civil cases that would all become fit cases for criminal fraud if the government's new and vastly enlarged fraudulent inducement theory is adopted."},{"src":"argument","who":"Mr. Dreeben","text":"It also tends to run aground because it infringes on turf that's covered by Skilling and McNally and would allow the government to prosecute a variety of kinds of things -- the -- through the guise of calling them property fraud when it cannot do so under honest services."}]},{"t":"case","label":"Neder v. United States","cite":"527 U.S. 1","y":1999,"id":"1998/97-1985","sc":1,"by":{"0":"19, 38, 39","1":"22","3":"15, 17, 18, 21, 42, 44","4":"7, 9, 10, 17"},"q":[{"src":"brief","b":0,"text":"the text or structure of the fraud statutes","cite":"527 U.S. 1, 2223"},{"src":"brief","b":0,"text":"a reasonable man would attach importance to its existence or nonexistence in determining his choice of action in the transaction in question,","cite":"527 U.S. at 22 n.5"},{"src":"brief","b":3,"text":"prohibit[] the ‘scheme to defraud,’ rather than the completed fraud.","cite":"527 U.S. at 25"},{"src":"brief","b":3,"text":"the presumption that Congress intended to incorporate the common-law meaning of the term ‘fraud’ in the","cite":"527 U.S. at 23 n.7"},{"src":"brief","b":4,"text":"clearly … inconsistent with the statutes Congress enacted.","cite":"527 U.S. 1, 25"},{"src":"brief","b":4,"text":"a natural tendency to influence, or [be] capable of influencing, the decision of the decisionmaking body to which it was addressed.","cite":"527 U.S. at 16"},{"src":"argument","who":"Mr. Dreeben","text":"And even if that doesn't hold true in every single case -- and I think, Justice Alito, Neder and cases like that suggest that there can be harmless error -- it should hold true in a case like this, where the government's new theory emerges only in its merits briefing in this Court and was abandoned by amendments to the indictment below."},{"src":"argument","who":"Mr. Feigin","text":"So, if we -- if we take the government's -- if -- if we're all agreed on the broader interests of this case, and it's -- the Court's not going to relitigate Shaw and Neder and introduce some sort of harm concept that it firmly rejected on page 467 of Shaw -- and I can -- I can get to why that is -- then, in this particular case, I think it's different from the kinds of cases that Mr."},{"src":"argument","who":"Mr. Feigin","text":"-- first of all, I think that this error could be con -- analogized, all -- although I will acknowledge that it's somewhat broader than the errors in those cases like the errors in Neder or --"}]},{"t":"case","label":"New Prime Inc. v. Oliveira","cite":"139 S. Ct. 532","y":2019,"id":"2018/17-340","sc":1,"by":{"0":"18","1":"34"},"q":[{"src":"brief","b":0,"text":"a fundamental canon of statutory construction that words generally should be interpreted as taking their ordinary meaning at the time Congress enacted the statute.","cite":"139 S. Ct. 532, 539"}]},{"t":"case","label":"Pasquantino v. United States","cite":"544 U.S. 349","y":2005,"id":"2004/03-725","sc":1,"by":{"0":"19, 20, 32","1":"22","3":"11, 16, 17, 32, 33"},"q":[{"src":"brief","b":0,"text":"has long been thought to be a species of property","cite":"544 U.S. 349, 356"},{"src":"brief","b":3,"text":"extend[s] to every species of valuable right and interest,","cite":"544 U.S. 349, 355"},{"src":"opinion","who":"Opinion of the Court (Justice Thomas)","text":"we have construed identical language in the wire and mail fraud statutes in pari materia.","cite":"544 U. S. 349, 355, n. 2"}]},{"t":"case","label":"Ruckelshaus v. Monsanto Co.","cite":"467 U.S. 986","y":1984,"id":"1983/83-196","sc":1,"by":{"0":"21"}},{"t":"case","label":"Salman v. United States","cite":"137 S. Ct. 420","y":2016,"id":"2016/15-628","sc":1,"by":{"0":"49"}},{"t":"case","label":"Scheidler v. Nat’l Org. for Women, Inc.","cite":"537 U.S. 393","y":2003,"id":"2002/01-1118","sc":1,"by":{"0":"33","2":"passim"},"q":[{"src":"brief","b":2,"text":"argue[d] that because the right to control the use and disposition of an asset is property, [the protestors], who interfered with, and in some instances completely disrupted, the ability of the clinics to function, obtained or attempted to obtain [the plaintiffs’] property.","cite":"537 U.S. at 401"},{"src":"brief","b":2,"text":"this ‘obtaining of property’ requirement included both a deprivation and acquisition of property.","cite":"537 U.S. at 403"}]},{"t":"case","label":"Sekhar v. United States","cite":"570 U.S. 729","y":2013,"id":"2012/12-357","sc":1,"by":{"0":"32, 33","2":"passim"},"q":[{"src":"brief","b":0,"text":"requires not only the deprivation but also the acquisition of property.","cite":"570 U.S. 729, 734"},{"src":"brief","b":2,"text":"would effectively discard the statutory requirement that property must be obtained from another.","cite":"570 U.S. 729"}]},{"t":"case","label":"Shaw v. United States","cite":"137 S. Ct. 462","y":2016,"id":"2016/15-5991","sc":1,"by":{"0":"28, 30","3":"21, 40","4":"11, 12"},"q":[{"src":"argument","who":"Justice Alito","text":"What do you say about the statement in Shaw that bank fraud requires no actual loss or intent to cause loss?"},{"src":"argument","who":"Mr. Dreeben","text":"And if you look at the -- the facts of Shaw, it involves someone who stole somebody's credentials to their account and used it to extract money from the bank."},{"src":"argument","who":"Mr. Feigin","text":"This Court in recent cases like Kelly and Shaw has referred to it as property. And the -- this Court nodded to the idea of a right-to-control theory, admittedly, without endorsing it, in both McNally and Cleveland."}]},{"t":"case","label":"Skilling v. United States","cite":"561 U.S. 358","y":2010,"id":"2009/08-1394","sc":1,"by":{"0":"passim","1":"passim","2":"1, 18, 19, 40","3":"16, 46, 47","4":"20, 21"},"q":[{"src":"brief","b":0,"text":"with one the mirror image of the other,","cite":"561 U.S. at 400"},{"src":"brief","b":1,"text":"‘scheme or artifice to defraud’ to include deprivations not only of money or property, but also of intangible rights,","cite":"561 U.S. at 400"},{"src":"brief","b":1,"text":"Unlike fraud in which the victim’s loss of money or property supplied the defendant’s gain, ... the honest-services theory targeted corruption that lacked similar symmetry.","cite":"561 U.S. at 400"},{"src":"brief","b":2,"text":"‘standards of moral uprightness, fundamental honesty, fair play and right dealing.’","cite":"561 U.S. at 418"},{"src":"brief","b":3,"text":"the victim’s loss of money or property supplied the defendant’s gain, with one the mirror image of the other.","cite":"561 U.S. at 400"},{"src":"argument","who":"Mr. Dreeben","text":"It also tends to run aground because it infringes on turf that's covered by Skilling and McNally and would allow the government to prosecute a variety of kinds of things -- the -- through the guise of calling them property fraud when it cannot do so under honest services."}]},{"t":"case","label":"Smith v. Shaughnessy","cite":"318 U.S. 176","y":1943,"id":"scdb/1942-122","sc":1,"by":{"0":"43"},"q":[{"src":"brief","b":0,"text":"slippery and elusive … cannot escape taxation so long as they are used in the world of business.","cite":"318 U.S. at 180"}]},{"t":"case","label":"United States v. Bass","cite":"404 U.S. 336","y":1971,"id":"1971/70-71","sc":1,"by":{"0":"48"}},{"t":"case","label":"United States v. Biaggi","cite":"909 F.2d 662","y":1990,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/909/662/","by":{"0":"17","1":"28, 29, 30"}},{"t":"case","label":"United States v. Binday","cite":"804 F.3d 558","y":2015,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/804/558/","by":{"0":"passim","1":"1, 8, 31","2":"34","3":"24, 25, 26, 27"},"q":[{"src":"brief","b":0,"text":"necessary to make discretionary economic decisions.","cite":"804 F.3d 558, 570"},{"src":"brief","b":0,"text":"[i]n a right-tocontrol case, ‘it is not necessary that a defendant intend that his misrepresentation actually inflict a financial loss—it suffices that a defendant intend that his misrepresentations induce a counterparty to enter a transaction without the relevant facts necessary to make an informed economic decision.’","cite":"804 F.3d 558, 579"},{"src":"brief","b":1,"text":"it is not necessary that a defendant intend that his misrepresentations actually inflict a financial loss—it suffices that a defendant intend that his misrepresentations induce a counterparty to enter a transaction without the relevant facts necessary to make an informed economic decision.","cite":"804 F.3d at 579"},{"src":"brief","b":2,"text":"‘information necessary to make discretionary economic decisions.’","cite":"804 F.3d 558, 570"},{"src":"brief","b":3,"text":"property interests * * * include the interest of a victim in controlling his or her own assets.","cite":"804 F.3d at 570"},{"src":"brief","b":3,"text":"enter[] into a discretionary economic transaction.","cite":"804 F.3d at 570"},{"src":"opinion","who":"Opinion of the Court (Justice Thomas)","text":"cognizable harm occurs where the defendant's scheme denies the victim the right to control its assets by depriving it of information necessary to make discretionary economic decisions.","cite":"804 F. 3d 558, 570"}]},{"t":"case","label":"United States v. Craft","cite":"535 U.S. 274","y":2002,"id":"2001/00-1831","sc":1,"by":{"0":"27, 42"},"q":[{"src":"brief","b":0,"text":"a collection of individual rights which, in certain combinations, constitute property.","cite":"535 U.S. 274, 278"}]},{"t":"case","label":"United States v. D’Amato","cite":"39 F.3d 1249","y":1994,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/39/1249/","by":{"0":"40"}},{"t":"case","label":"United States v. Davis","cite":"139 S. Ct. 2319","y":2019,"id":"2018/18-431","sc":1,"by":{"0":"33, 48"},"q":[{"src":"brief","b":0,"text":"that the same language in related statutes carries a consistent meaning,","cite":"139 S. Ct. 2319, 2329"},{"src":"brief","b":0,"text":"that ambiguities about the breadth of a criminal statute should be resolved in the defendant’s favor.","cite":"139 S. Ct. 2319, 2333"}]},{"t":"case","label":"United States v. Fagan","cite":"821 F.2d 1002","y":1987,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/821/1002/","by":{"0":"39","1":"passim"}},{"t":"case","label":"United States v. Finazzo","cite":"850 F.3d 94","y":2017,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/850/94/","by":{"0":"39","1":"1, 8, 30, 31, 33","2":"3, 26, 27, 41","3":"passim","4":"13, 14"},"q":[{"src":"brief","b":0,"text":"defendants contemplated some actual, cognizable harm or injury to their victims,","cite":"850 F.3d 94, 107 n.15"},{"src":"brief","b":1,"text":"A ‘cognizable harm occurs where the defendant’s scheme denies the victim the right to control its assets by depriving it of information necessary to make discretionary economic decisions.","cite":"850 F.3d at 111"},{"src":"brief","b":2,"text":"the mail and wire fraud statutes do not require that the property involved in the fraud be ‘obtainable.’","cite":"850 F.3d 94, 105"},{"src":"brief","b":2,"text":"to extend Sekhar’s obtainability requirement to the mail and wire fraud statutes.","cite":"850 F.3d at 107"},{"src":"brief","b":3,"text":"common thread of [its] decisions is that misrepresentations or non-disclosure of information cannot support a conviction under the ‘right to control’ theory unless those misrepresentations or non-disclosures can or do result in tangible economic harm.","cite":"850 F.3d 94, 111"},{"src":"brief","b":3,"text":"necessarily creates a risk of tangible economic harm.","cite":"850 F.3d at 111"},{"src":"argument","who":"Mr. Dreeben","text":"Overcharging, overpaying for services that were not performed, that is the kind of conventional fraud case that the government points to in the Finazzo case."}]},{"t":"case","label":"United States v. Gen. Motors Corp.","cite":"323 U.S. 373","y":1945,"id":"scdb/1944-056","sc":1,"by":{"0":"21"},"q":[{"src":"brief","b":0,"text":"Property rights in a physical thing have been described as the rights ‘to possess, use and dispose of it.’","cite":"323 U.S. 373, 378"}]},{"t":"case","label":"United States v. Johnson","cite":"945 F.3d 606","y":2019,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/945/606/","by":{"0":"38, 40","3":"30, 31"},"q":[{"src":"brief","b":0,"text":"used the wires [or mail] to further that scheme.","cite":"945 F.3d 606, 612"},{"src":"brief","b":3,"text":"whether the defendant’s deception ‘affect[ed] the very nature of the bargain.’","cite":"945 F.3d 606, 612"},{"src":"brief","b":3,"text":"‘that defendants contemplated some actual, cognizable harm or injury to their victims’ by deceiving them.","cite":"945 F.3d at 614"}]},{"t":"case","label":"United States v. Kerkman","cite":"866 F.2d 877","y":1989,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/866/877/","by":{"0":"17","1":"28, 29"}},{"t":"case","label":"United States v. Little","cite":"889 F.2d 1367","y":1989,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/889/1367/","by":{"0":"17","1":"28, 29","2":"28"},"q":[{"src":"opinion","who":"Opinion of the Court (Justice Thomas)","text":"eliminating the requirement of property loss","cite":"889 F. 2d 1367, 1368–1369"}]},{"t":"case","label":"United States v. Miller","cite":"953 F.3d 1095","y":2020,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/953/1095/","by":{"0":"28, 29"},"q":[{"src":"brief","b":0,"text":"It follows that to be guilty of wire fraud, a defendant must act with the intent not only to make false statements or utilize other forms of deception, but also to deprive a victim of money or property by means of those deceptions.","cite":"953 F.3d at 1101"}]},{"t":"case","label":"United States v. Novak","cite":"443 F.3d 150","y":2006,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/443/150/","by":{"0":"45"}},{"t":"case","label":"United States v. Ochs","cite":"842 F.2d 515","y":1988,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/842/515/","by":{"0":"37","1":"30"},"q":[{"src":"brief","b":0,"text":"[C]ourts are [not] free simply to recharacterize every breach of fiduciary duty as a financial harm, and thereby to let in through the back door the very prosecution theory that the Supreme Court tossed out the front.","cite":"842 F.2d 515, 527"},{"src":"brief","b":1,"text":"let in through the back door the very prosecution theory that the Supreme Court tossed out the front.","cite":"842 F.2d 515, 527"}]},{"t":"case","label":"United States v. Regent Off. Supply Co.","cite":"421 F.2d 1174","y":1970,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/421/1174/","by":{"0":"40, 44, 45"}},{"t":"case","label":"United States v. Rowe","cite":"56 F.2d 747","y":1932,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/56/747/","by":{"0":"17","3":"21, 40","4":"12"},"q":[{"src":"brief","b":3,"text":"‘a man is nonetheless cheated out of his property, when he is induced to part with it by fraud,’ even if ‘he gets a quid pro quo of equal value.’","cite":"56 F.2d 747, 749"}]},{"t":"case","label":"United States v. Sadler","cite":"750 F.3d 585","y":2014,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/750/585/","by":{"0":"35, 36","2":"39"},"q":[{"src":"brief","b":0,"text":"Congress’s reverberating silence about other intangible interests tells us all we need to know","cite":"750 F.3d at 591"}]},{"t":"case","label":"United States v. Santos","cite":"553 U.S. 507","y":2008,"id":"2007/06-1005","sc":1,"by":{"0":"48"},"q":[{"src":"brief","b":0,"text":"making criminal law in Congress’s stead.","cite":"553 U.S. 507, 514"}]},{"t":"case","label":"United States v. Schwartz","cite":"924 F.2d 410","y":1991,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/924/410/","by":{"0":"46"}},{"t":"case","label":"United States v. Shellef","cite":"507 F.3d 82","y":2007,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/507/82/","by":{"0":"8, 44, 45, 46"},"q":[{"src":"brief","b":0,"text":"a fine line between schemes that do no more than cause their victims to enter into transactions they would otherwise avoid—which do not violate the mail and wire fraud statutes—and schemes that depend for their completion on a misrepresentation of an essential element of the bargain—which do.","cite":"507 F.3d 82, 108"},{"src":"brief","b":0,"text":"induced [a party] to enter into a transaction it would otherwise have avoided","cite":"507 F.3d at 109"}]},{"t":"case","label":"United States v. Shyres","cite":"898 F.2d 647","y":1990,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/898/647/","by":{"0":"17","1":"28, 29"}},{"t":"case","label":"United States v. Starr","cite":"816 F.2d 94","y":1987,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/816/94/","by":{"0":"45","4":"12"}},{"t":"case","label":"United States v. Taylor","cite":"142 S. Ct. 2015","y":2022,"id":"2021/20-1459","sc":1,"by":{"0":"11, 41"},"q":[{"src":"brief","b":0,"text":"do[es] not lightly assume Congress adopts two separate clauses in the same law to perform the same work.","cite":"142 S. Ct. 2015, 2024"}]},{"t":"case","label":"United States v. Wallach","cite":"935 F.2d 445","y":1991,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/935/445/","by":{"0":"passim","1":"passim","2":"28, 41"},"q":[{"src":"brief","b":2,"text":"the right to complete and accurate information is one of the most essential sticks in the bundle of rights that comprise a stockholder’s property interest.","cite":"935 F.2d 445, 463"},{"src":"argument","who":"Justice Kavanaugh","text":"But like in the Wallach case, going back --"},{"src":"argument","who":"Justice Kavanaugh","text":"-- the Wallach case, and, you know, there -- we can name the names. There -- the government was not just some bystander here. Again, it's not you personally."},{"src":"argument","who":"Mr. Feigin","text":"Your Honor, I suppose we could debate particular facts of particular cases, but Wallach in particular is a case in which the --"}]},{"t":"case","label":"United States v. Walters","cite":"997 F.2d 1219","y":1993,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/997/1219/","by":{"0":"31","2":"18"}},{"t":"case","label":"United States v. Yates","cite":"16 F.4th 256","y":2021,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.4th/16/256/","by":{"0":"37","1":"30"}},{"t":"usc","label":"18 U.S.C. § 2","url":"https://www.law.cornell.edu/uscode/text/18/2","by":{"0":"5"}},{"t":"usc","label":"18 U.S.C. § 1341","url":"https://www.law.cornell.edu/uscode/text/18/1341","stext":{"head":"§1341. Frauds and swindles","paras":[[0,"Whoever, having devised or intending to devise any scheme or artifice to defraud, or for obtaining money or property by means of false or fraudulent pretenses, representations, or promises, or to sell, dispose of, loan, exchange, alter, give away, distribute, supply, or furnish or procure for unlawful use any counterfeit or spurious coin, obligation, security, or other article, or anything represented to be or intimated or held out to be such counterfeit or spurious article, for the purpose of executing such scheme or artifice or attempting so to do, places in any post office or authorized depository for mail matter, any matter or thing whatever to be sent or delivered by the Postal Service, or deposits or causes to be deposited any matter or thing whatever to be sent or delivered by any private or commercial interstate carrier, or takes or receives therefrom, any such matter or thing, or knowingly causes to be delivered by mail or such carrier according to the direction thereon, or at the place at which it is directed to be delivered by the person to whom it is addressed, any such matter or thing, shall be fined under this title or imprisoned not more than 20 years, or both. If the violation occurs in relation to, or involving any benefit authorized, transported, transmitted, transferred, disbursed, or paid in connection with, a presidentially declared major disaster or emergency (as those terms are defined in section 102 of the Robert T. Stafford Disaster Relief and Emergency Assistance Act (42 U.S.C. 5122)), or affects a financial institution, such person shall be fined not more than $1,000,000 or imprisoned not more than 30 years, or both."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1341?type=usc&year=mostrecent&link-type=html"},"by":{"0":"31","1":"passim","2":"3, 15, 16","3":"15"},"q":[{"src":"brief","b":0,"text":"scheme … to obtain money or property","cite":"18 U.S.C. §§ 1341, 1343"},{"src":"brief","b":1,"text":"any scheme or artifice to defraud, or for obtaining money or property by means of false or fraudulent pretenses, representations, or promises.","cite":"18 U.S.C. §§ 1341, 1343"},{"src":"brief","b":2,"text":"any scheme or artifice to defraud, or for obtaining money or property by means of false or fraudulent pretenses, representations or promises.","cite":"18 U.S.C. §§ 1341, 1343"}]},{"t":"usc","label":"18 U.S.C. § 1343","url":"https://www.law.cornell.edu/uscode/text/18/1343","stext":{"head":"§1343. Fraud by wire, radio, or television","paras":[[0,"Whoever, having devised or intending to devise any scheme or artifice to defraud, or for obtaining money or property by means of false or fraudulent pretenses, representations, or promises, transmits or causes to be transmitted by means of wire, radio, or television communication in interstate or foreign commerce, any writings, signs, signals, pictures, or sounds for the purpose of executing such scheme or artifice, shall be fined under this title or imprisoned not more than 20 years, or both. If the violation occurs in relation to, or involving any benefit authorized, transported, transmitted, transferred, disbursed, or paid in connection with, a presidentially declared major disaster or emergency (as those terms are defined in section 102 of the Robert T. Stafford Disaster Relief and Emergency Assistance Act (42 U.S.C. 5122)), or affects a financial institution, such person shall be fined not more than $1,000,000 or imprisoned not more than 30 years, or both."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1343?type=usc&year=mostrecent&link-type=html"},"by":{"0":"2, 5, 31","1":"passim","2":"3, 6, 15, 16","3":"passim"},"q":[{"src":"brief","b":3,"text":"any scheme or artifice to defraud, or for obtaining money or property by means of false or fraudulent pretenses, representations, or promises.","cite":"18 U.S.C. 1343"},{"src":"brief","b":3,"text":"to defraud, or for obtaining money or property,","cite":"18 U.S.C. 1343"}]},{"t":"usc","label":"18 U.S.C. § 1346","url":"https://www.law.cornell.edu/uscode/text/18/1346","stext":{"head":"§1346. Definition of \"scheme or artifice to defraud\"","paras":[[0,"For the purposes of this chapter, the term \"scheme or artifice to defraud\" includes a scheme or artifice to deprive another of the intangible right of honest services."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1346?type=usc&year=mostrecent&link-type=html"},"by":{"0":"10, 14, 35, 36","1":"passim","3":"46"},"q":[{"src":"brief","b":0,"text":"the intangible right of honest services,","cite":"18 U.S.C. § 1346"},{"src":"brief","b":0,"text":"a scheme or artifice to deprive another of the intangible right of honest services.","cite":"18 U.S.C. § 1346"},{"src":"argument","who":"Mr. Dreeben","text":"So the Court could also say: Congress reinstated certain intangible rights in the honest-services amendment, Section 1346. The right to control assets is not one of them."}]},{"t":"usc","label":"18 U.S.C. § 1349","url":"https://www.law.cornell.edu/uscode/text/18/1349","stext":{"head":"§1349. Attempt and conspiracy","paras":[[0,"Any person who attempts or conspires to commit any offense under this chapter shall be subject to the same penalties as those prescribed for the offense, the commission of which was the object of the attempt or conspiracy."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1349?type=usc&year=mostrecent&link-type=html"},"by":{"0":"4","1":"5","2":"6","3":"2, 8"},"q":[{"src":"brief","b":3,"text":"[a]ny person who attempts or conspires to commit any offense under this chapter shall be subject to the same penalties as those prescribed for the offense, the commission of which was the object of the attempt or conspiracy.","cite":"18 U.S.C. 1349"}]},{"t":"usc","label":"18 U.S.C. § 1951","url":"https://www.law.cornell.edu/uscode/text/18/1951","stext":{"head":"§1951. Interference with commerce by threats or violence","paras":[[0,"(a) Whoever in any way or degree obstructs, delays, or affects commerce or the movement of any article or commodity in commerce, by robbery or extortion or attempts or conspires so to do, or commits or threatens physical violence to any person or property in furtherance of a plan or purpose to do anything in violation of this section shall be fined under this title or imprisoned not more than twenty years, or both."],[0,"(b) As used in this section—"],[1,"(1) The term \"robbery\" means the unlawful taking or obtaining of personal property from the person or in the presence of another, against his will, by means of actual or threatened force, or violence, or fear of injury, immediate or future, to his person or property, or property in his custody or possession, or the person or property of a relative or member of his family or of anyone in his company at the time of the taking or obtaining."],[1,"(2) The term \"extortion\" means the obtaining of property from another, with his consent, induced by wrongful use of actual or threatened force, violence, or fear, or under color of official right."],[1,"(3) The term \"commerce\" means commerce within the District of Columbia, or any Territory or Possession of the United States; all commerce between any point in a State, Territory, Possession, or the District of Columbia and any point outside thereof; all commerce between points within the same State through any place outside such State; and all other commerce over which the United States has jurisdiction."],[0,"(c) This section shall not be construed to repeal, modify or affect section 17 of Title 15, sections 52, 101–115, 151–166 of Title 29 or sections 151–188 of Title 45."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1951?type=usc&year=mostrecent&link-type=html"},"by":{"0":"32","2":"19"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"2"}},{"t":"case","label":"Ingber v. Enzor","cite":"841 F.2d 450","y":1988,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/841/450/","by":{"1":"30"}},{"t":"case","label":"Penturelli v. Spector, Cohen, Gadon & Rosen","cite":"779 F.2d 160","y":1985,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/779/160/","by":{"1":"23"}},{"t":"case","label":"Ranke v. United States","cite":"873 F.2d 1033","y":1989,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/873/1033/","by":{"1":"28, 29"}},{"t":"case","label":"Shushan v. United States","cite":"117 F.2d 110","y":1941,"url":"https://www.courtlistener.com/c/F.2d/117/110/","by":{"1":"14"}},{"t":"case","label":"Sisson v. Ruby","cite":"497 U.S. 358","y":1990,"id":"1989/88-2041","sc":1,"by":{"1":"26"},"q":[{"src":"brief","b":1,"text":"could not, since the [case] did not present the question.","cite":"497 U.S. 358, 373"}]},{"t":"case","label":"Sorich v. United States","cite":"555 U.S. 1204","y":2009,"url":"https://supreme.justia.com/cases/federal/us/555/1204/","sc":1,"by":{"1":"15, 32"},"q":[{"src":"brief","b":1,"text":"staggeringly broad swath of behavior, including misconduct not only by public officials and employees but also by private employees and corporate fiduciaries.","cite":"555 U.S. 1204, 1204"}]},{"t":"case","label":"United States v. Bein","cite":"728 F.2d 107","y":1984,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/728/107/","by":{"1":"23"}},{"t":"case","label":"United States v. Bush","cite":"522 F.2d 641","y":1975,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/522/641/","by":{"1":"24"}},{"t":"case","label":"United States v. Cauble","cite":"706 F.2d 1322","y":1983,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/706/1322/","by":{"1":"23"}},{"t":"case","label":"United States v. Conner","cite":"752 F.2d 566","y":1985,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/752/566/","by":{"1":"23-24"}},{"t":"case","label":"United States v. George","cite":"477 F.2d 508","y":1973,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/477/508/","by":{"1":"23, 24, 28"}},{"t":"case","label":"United States v. Iaciofano","cite":"734 F.2d 87","y":1984,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/734/87/","by":{"1":"23"}},{"t":"case","label":"United States v. Johnson","cite":"496 F.2d 1131","y":1974,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/496/1131/","by":{"1":"23"}},{"t":"case","label":"United States v. Lebedev","cite":"932 F.3d 40","y":2019,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/932/40/","by":{"1":"8, 31, 33","2":"34"},"q":[{"src":"brief","b":1,"text":"through the withholding or inaccurate reporting of information that could impact on economic decisions, [he] deprived some person or entity of potentially valuable information.","cite":"932 F.3d 40, 48"},{"src":"brief","b":2,"text":"‘right-to-control theory’ of wire fraud … allows for conviction on ‘a showing that the defendant, through the withholding or inaccurate reporting of information that could impact on economic decisions, deprived some person or entity of potentially valuable economic information.’","cite":"932 F.3d 40, 48"},{"src":"opinion","who":"Opinion of the Court (Justice Thomas)","text":"the property interests protected by the wire fraud statute include the interest of a victim in controlling his or her own assets.","cite":"932 F. 3d 40, 48"}]},{"t":"case","label":"United States v. Rico Indus.","cite":"854 F.2d 710","y":1988,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/854/710/","by":{"1":"27"}},{"t":"case","label":"United States v. Ron Pair Enters.","cite":"489 U.S. 235","y":1989,"id":"1988/87-1043","sc":1,"by":{"1":"33"}},{"t":"case","label":"United States v. Von Barta","cite":"635 F.2d 999","y":1980,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/635/999/","by":{"1":"23, 24"}},{"t":"case","label":"Abramski v. United States","cite":"573 U.S. 169","y":2014,"id":"2013/12-1493","sc":1,"by":{"2":"24"}},{"t":"case","label":"Evans v. United States","cite":"504 U.S. 255","y":1992,"id":"1991/90-6105","sc":1,"by":{"2":"25"}},{"t":"case","label":"Gamble v. United States","cite":"139 S. Ct. 1960","y":2019,"id":"2018/17-646","sc":1,"by":{"2":"1"}},{"t":"case","label":"Honeycutt v. United States","cite":"137 S. Ct. 1626","y":2017,"id":"2016/16-142","sc":1,"by":{"2":"23, 24"}},{"t":"case","label":"Kungys v. United States","cite":"485 U.S. 759","y":1988,"id":"1986/86-228","sc":1,"by":{"2":"29"}},{"t":"case","label":"Loughrin v. United States","cite":"573 U.S. 351","y":2014,"id":"2013/13-316","sc":1,"by":{"2":"17","3":"17, 22, 47, 48","4":"12"},"q":[{"src":"brief","b":3,"text":"is the mechanism naturally inducing [the victim] to part with money [or property].","cite":"573 U.S. 351, 363"},{"src":"argument","who":"Mr. Dreeben","text":"That borrows from this Court's decision in Loughrin to say that it has the natural tendency to induce the person to part with property. That also was not in the jury instructions."}]},{"t":"case","label":"Marinello v. United States","cite":"138 S. Ct. 1101","y":2018,"id":"2017/16-1144","sc":1,"by":{"2":"40","4":"16"},"q":[{"src":"brief","b":2,"text":"power in the hands of the prosecutor.","cite":"138 S. Ct. 1101, 1108"},{"src":"brief","b":4,"text":"could result in the nonuniform execution of that power across time and geographic location.","cite":"138 S. Ct. 1101, 1108-09"}]},{"t":"case","label":"Morissette v. United States","cite":"342 U.S. 246","y":1952,"id":"scdb/1951-028","sc":1,"by":{"2":"21"}},{"t":"case","label":"Nichols v. United States","cite":"578 U.S. 104","y":2016,"id":"2015/15-5238","sc":1,"by":{"2":"24"},"q":[{"src":"brief","b":2,"text":"interpret[s] criminal statutes, like other statutes, in a manner consistent with ordinary English usage.","cite":"578 U.S. 104, 111"}]},{"t":"case","label":"Porcelli v. United States","cite":"404 F.3d 157","y":2005,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/404/157/","by":{"2":"26"},"q":[{"src":"brief","b":2,"text":"The fact that the Hobbs Act and the mail and wire fraud statutes contain the word ‘obtain’ does not necessitate imposing Scheidler’s construction of a wholly separate statute onto this Court’s pre-existing construction of the mail fraud statute.","cite":"404 F.3d 157, 162"}]},{"t":"case","label":"Southwest Airlines Co. v. Saxon","cite":"142 S. Ct. 1783","y":2022,"id":"2021/21-309","sc":1,"by":{"2":"33"},"q":[{"src":"brief","b":2,"text":"the different term denotes a different idea.","cite":"142 S. Ct. 1783, 1789"}]},{"t":"case","label":"Taylor v. United States","cite":"495 U.S. 575","y":1990,"id":"1989/88-7194","sc":1,"by":{"2":"21"}},{"t":"case","label":"United States v. Clapps","cite":"732 F.2d 1148","y":1984,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/732/1148/","by":{"2":"16, 17"}},{"t":"case","label":"vii United States v. Gatto","cite":"986 F.3d 104","y":2021,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/986/104/","by":{"2":"3, 39"},"q":[{"src":"brief","b":2,"text":"an informed economic decision about what to do with its money or property.","cite":"986 F.3d 104, 126"}]},{"t":"case","label":"United States v. Hedaithy","cite":"392 F.3d 580","y":2004,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/392/580/","by":{"2":"27"}},{"t":"case","label":"United States v. Nardello","cite":"393 U.S. 286","y":1969,"id":"1968/51","sc":1,"by":{"2":"21"},"q":[{"src":"brief","b":2,"text":"received ‘something of value from’ [the other party] that they could exercise, transfer, or sell.","cite":"393 U.S. 286, 290"}]},{"t":"case","label":"United States v. Sekhar","cite":"683 F.3d 436","y":2012,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/683/436/","by":{"2":"22"}},{"t":"case","label":"United States v. Takhalov","cite":"827 F.3d 1307","y":2016,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/827/1307/","by":{"2":"39"}},{"t":"case","label":"United States v. Weimert","cite":"819 F.3d 351","y":2016,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/819/351/","by":{"2":"38"}},{"t":"case","label":"Wilson v. Ward Lumber","cite":"67 F. 674","y":1895,"court":"C.C.E.D. Mo.","url":"https://www.courtlistener.com/c/F./67/674/","by":{"2":"31"},"q":[{"src":"brief","b":2,"text":"any external object over which the right of property is exercised.","cite":"67 F. 674, 677"}]},{"t":"case","label":"viii Yates v. United States","cite":"574 U.S. 528","y":2015,"id":"2014/13-7451","sc":1,"by":{"2":"1"}},{"t":"usc","label":"18 U.S.C. § 1001","url":"https://www.law.cornell.edu/uscode/text/18/1001","by":{"2":"12"}},{"t":"usc","label":"18 U.S.C. § 1964","url":"https://www.law.cornell.edu/uscode/text/18/1964","by":{"2":"32"}},{"t":"usc","label":"20 U.S.C. § 4302","url":"https://www.law.cornell.edu/uscode/text/20/4302","by":{"2":"32"}},{"t":"usc","label":"21 U.S.C. § 853","url":"https://www.law.cornell.edu/uscode/text/21/853","stext":{"head":"§853. Criminal forfeitures","paras":[[0,"(a) Property subject to criminal forfeiture"],[0,"Any person convicted of a violation of this subchapter or subchapter II punishable by imprisonment for more than one year shall forfeit to the United States, irrespective of any provision of State law—"],[1,"(1) any property constituting, or derived from, any proceeds the person obtained, directly or indirectly, as the result of such violation;"],[1,"(2) any of the person's property used, or intended to be used, in any manner or part, to commit, or to facilitate the commission of, such violation; and"],[1,"(3) in the case of a person convicted of engaging in a continuing criminal enterprise in violation of section 848 of this title, the person shall forfeit, in addition to any property described in paragraph (1) or (2), any of his interest in, claims against, and property or contractual rights affording a source of control over, the continuing criminal enterprise."],[0,"The court, in imposing sentence on such person, shall order, in addition to any other sentence imposed pursuant to this subchapter or subchapter II, that the person forfeit to the United States all property described in this subsection. In lieu of a fine otherwise authorized by this part, a defendant who derives profits or other proceeds from an offense may be fined not more than twice the gross profits or other proceeds."],[0,"(b) Meaning of term \"property\""],[0,"Property subject to criminal forfeiture under this section includes—"],[1,"(1) real property, including things growing on, affixed to, and found in land; and"],[1,"(2) tangible and intangible personal property, including rights, privileges, interests, claims, and securities."],[0,"(c) Third party transfers"],[0,"All right, title, and interest in property described in subsection (a) vests in the United States upon the commission of the act giving rise to forfeiture under this section. Any such property that is subsequently transferred to a person other than the defendant may be the subject of a special verdict of forfeiture and thereafter shall be ordered forfeited to the United States, unless the transferee establishes in a hearing pursuant to subsection (n) that he is a bona fide purchaser for value of such property who at the time of purchase was reasonably without cause to believe that the property was subject to forfeiture under this section."],[0,"(d) Rebuttable presumption"],[0,"There is a rebuttable presumption at trial that any property of a person convicted of a felony under this subchapter or subchapter II is subject to forfeiture under this section if the United States establishes by a preponderance of the evidence that—"],[1,"(1) such property was acquired by such person during the period of the violation of this subchapter or subchapter II or within a reasonable time after such period; and"],[1,"(2) there was no likely source for such property other than the violation of this subchapter or subchapter II."],[0,"(e) Protective orders"],[0,"(1) Upon application of the United States, the court may enter a restraining order or injunction, require the execution of a satisfactory performance bond, or take any other action to preserve the availability of property described in subsection (a) for forfeiture under this section—"],[1,"(A) upon the filing of an indictment or information charging a violation of this subchapter or subchapter II for which criminal forfeiture may be ordered under this section and alleging that the property with respect to which the order is sought would, in the event of conviction, be subject to forfeiture under this section; or"],[1,"(B) prior to the filing of such an indictment or information, if, after notice to persons appearing to have an interest in the property and opportunity for a hearing, the court determines that—"],[2,"(i) there is a substantial probability that the United States will prevail on the issue of forfeiture and that failure to enter the order will result in the property being destroyed, removed from the jurisdiction of the court, or otherwise made unavailable for forfeiture; and"],[2,"(ii) the need to preserve the availability of the property through the entry of the requested order outweighs the hardship on any party against whom the order is to be entered:"],[0,"Provided, however, That an order entered pursuant to subparagraph (B) shall be effective for not more than ninety days, unless extended by the court for good cause shown or unless an indictment or information described in subparagraph (A) has been filed."],[0,"(2) A temporary restraining order under this subsection may be entered upon application of the United States without notice or opportunity for a hearing when an information or indictment has not yet been filed with respect to the property, if the United States demonstrates that there is probable cause to believe that the property with respect to which the order is sought would, in the event of conviction, be subject to forfeiture under this section and that provision of notice will jeopardize the availability of the property for forfeiture. Such a temporary order shall expire not more than fourteen days after the date on which it is entered, unless extended for good cause shown or unless the party against whom it is entered consents to an extension for a longer period. A hearing requested concerning an order entered under this paragraph shall be held at the earliest possible time and prior to the expiration of the temporary order."],[0,"(3) The court may receive and consider, at a hearing held pursuant to this subsection, evidence and information that would be inadmissible under the Federal Rules of Evidence."],[0,"(4) Order to repatriate and deposit.—"],[1,"(A) In general.—Pursuant to its authority to enter a pretrial restraining order under this section, the court may order a defendant to repatriate any property that may be seized and forfeited, and to deposit that property pending trial in the registry of the court, or with the United States Marshals Service or the Secretary of the Treasury, in an interest-bearing account, if appropriate."],[1,"(B) Failure to comply.—Failure to comply with an order under this subsection, or an order to repatriate property under subsection (p), shall be punishable as a civil or criminal contempt of court, and may also result in an enhancement of the sentence of the defendant under the obstruction of justice provision of the Federal Sentencing Guidelines."],[0,"(f) Warrant of seizure"],[0,"The Government may request the issuance of a warrant authorizing the seizure of property subject to forfeiture under this section in the same manner as provided for a search warrant. If the court determines that there is probable cause to believe that the property to be seized would, in the event of conviction, be subject to forfeiture and that an order under subsection (e) may not be sufficient to assure the availability of the property for forfeiture, the court shall issue a warrant authorizing the seizure of such property."],[0,"(g) Execution"],[0,"Upon entry of an order of forfeiture under this section, the court shall authorize the Attorney General to seize all property ordered forfeited upon such terms and conditions as the court shall deem proper. Following entry of an order declaring the property forfeited, the court may, upon application of the United States, enter such appropriate restraining orders or injunctions, require the execution of satisfactory performance bonds, appoint receivers, conservators, appraisers, accountants, or trustees, or take any other action to protect the interest of the United States in the property ordered forfeited. Any income accruing to or derived from property ordered forfeited under this section may be used to offset ordinary and necessary expenses to the property which are required by law, or which are necessary to protect the interests of the United States or third parties."],[0,"(h) Disposition of property"],[0,"Following the seizure of property ordered forfeited under this section, the Attorney General shall direct the disposition of the property by sale or any other commercially feasible means, making due provision for the rights of any innocent persons. Any property right or interest not exercisable by, or transferable for value to, the United States shall expire and shall not revert to the defendant, nor shall the defendant or any person acting in concert with him or on his behalf be eligible to purchase forfeited property at any sale held by the United States. Upon application of a person, other than the defendant or a person acting in concert with him or on his behalf, the court may restrain or stay the sale or disposition of the property pending the conclusion of any appeal of the criminal case giving rise to the forfeiture, if the applicant demonstrates that proceeding with the sale or disposition of the property will result in irreparable injury, harm, or loss to him."],[0,"(i) Authority of the Attorney General"],[0,"With respect to property ordered forfeited under this section, the Attorney General is authorized to—"],[1,"(1) grant petitions for mitigation or remission of forfeiture, restore forfeited property to victims of a violation of this subchapter, or take any other action to protect the rights of innocent persons which is in the interest of justice and which is not inconsistent with the provisions of this section;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/853?type=usc&year=mostrecent&link-type=html"},"by":{"2":"23"},"q":[{"src":"brief","b":2,"text":"property constituting, or derived from, any proceeds the person obtained, directly or indirectly, as the result of","cite":"21 U.S.C. § 853(a)(1)"}]},{"t":"case","label":"Buchanan v. Warley","cite":"245 U.S. 60","y":1917,"id":"1900-1940/245us60","sc":1,"by":{"3":"25"},"q":[{"src":"brief","b":3,"text":"consists of the free use, enjoyment, and disposal of a person’s acquisitions without control or diminution save by the law of the land.","cite":"245 U.S. 60, 74"}]},{"t":"case","label":"Chiarella v. United States","cite":"445 U.S. 222","y":1980,"id":"1979/78-1202","sc":1,"by":{"3":"17, 20, 47","4":"5"},"q":[{"src":"brief","b":3,"text":"At common law, misrepresentation made for the purpose of inducing reliance upon the false statement is fraudulent.","cite":"445 U.S. at 227"},{"src":"brief","b":4,"text":"cannot affirm a criminal conviction on the basis of a theory not presented to the jury.","cite":"445 U.S. 222, 236"},{"src":"argument","who":"Mr. Dreeben","text":"Well, Justice Barrett, the reason why I don't think that it's an appropriate issue for the Second Circuit to get on remand is this Court's repeated statements in cases like Dunn, McCormick, and specifically Chiarella and McNally itself that the Court cannot affirm a criminal conviction on the basis of a theory not presented to the jury."},{"src":"argument","who":"Mr. Dreeben","text":"And in a case like Chiarella, which is pretty much on all fours like the -- with this case, the Court simply entered a -- an opinion that said reverse."},{"src":"argument","who":"Mr. Dreeben","text":"If that were true, the government would have been able to defend the insider trading conviction in Chiarella by saying: Decide the misappropriation doctrine."}]},{"t":"case","label":"Janes v. Trustees of Mercer Univ.","cite":"17 Ga. 515","y":1855,"url":"https://www.courtlistener.com/c/Ga./17/515/","by":{"3":"19"}},{"t":"case","label":"J.I. Case Threshing Mach. Co. v. Webb","cite":"181 S.W. 853","y":1915,"court":"Tex. Civ. App.","url":"https://www.courtlistener.com/c/S.W./181/853/","by":{"3":"19"},"q":[{"src":"argument","who":"Chief Justice Roberts","text":"We'll hear argument next in Case 21-1170, Ciminelli versus United States. Mr. Dreeben. ORAL ARGUMENT OF MICHAEL R. DREEBEN ON BEHALF OF THE PETITIONER"}]},{"t":"case","label":"Junius Constr. Co. v. Cohen","cite":"178 N.E. 672","y":1931,"court":"N.Y.","url":"https://www.courtlistener.com/c/N.E./178/672/","by":{"3":"18"}},{"t":"case","label":"Musacchio v. United States","cite":"577 U.S. 237","y":2016,"id":"2015/14-1095","sc":1,"by":{"3":"31","4":"5, 6"}},{"t":"case","label":"Schmuck v. United States","cite":"489 U.S. 705","y":1989,"id":"1988/87-6431","sc":1,"by":{"3":"29"}},{"t":"case","label":"State v. Mills","cite":"17 Me. 211","y":1840,"url":"https://www.courtlistener.com/c/Me./17/211/","by":{"3":"19","4":"8, 9"}},{"t":"case","label":"United States v. Gaudin","cite":"515 U.S. 506","y":1995,"id":"1994/94-514","sc":1,"by":{"3":"44","4":"18"}},{"t":"case","label":"United States v. Jabar","cite":"19 F.4th 66","y":2021,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.4th/19/66/","by":{"3":"30"}},{"t":"case","label":"United States v. Leahy","cite":"464 F.3d 773","y":2006,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/464/773/","by":{"3":"23"}},{"t":"case","label":"United States v. New S. Farm & Home Co.","cite":"241 U.S. 64","y":1916,"id":"scdb/1915-212","sc":1,"by":{"3":"29, 45"}},{"t":"case","label":"United States v. Maxwell","cite":"579 F.3d 1282","y":2009,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/579/1282/","by":{"3":"20"}},{"t":"case","label":"United States v. Mittelstaedt","cite":"31 F.3d 1208","y":1994,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/31/1208/","by":{"3":"28"}},{"t":"case","label":"United States v. Sampson","cite":"371 U.S. 75","y":1962,"id":"1962/69","sc":1,"by":{"3":"40","4":"12"}},{"t":"case","label":"United States v. Williams","cite":"553 U.S. 285","y":2008,"id":"2007/06-694","sc":1,"by":{"3":"44"}},{"t":"case","label":"United States v. Viloski","cite":"557 Fed. Appx. 28","y":2014,"court":"2d Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./557/28/","by":{"3":"28"}},{"t":"case","label":"Universal Health Servs., Inc. v. United States","cite":"579 U.S. 176","y":2016,"id":"2015/15-7","sc":1,"by":{"3":"13, 18, 30, 43, 44","4":"17, 22"},"q":[{"src":"brief","b":3,"text":"a misrepresentation is material if it ‘went to the very essence of the bargain.’","cite":"579 U.S. at 193 n.5"},{"src":"brief","b":3,"text":"went to the very essence of the bargain.","cite":"579 U.S. at 193 n.5"},{"src":"argument","who":"Mr. Feigin","text":"In particular, what we think the Second Circuit has done that's really its sort of fundamental conceptual mistake is, instead of housing the -- its idea that there needs to be some way in which the victim is not getting what it's bargained for in materiality, where we think it properly belongs and where the Court put it in, for example, Universal Health Services, interpreting the standard definition of materiality in the particular context of contracting, it has added this tangible harm requirement that goes into the property element."}]},{"t":"case","label":"Washington Post Co. v. Sorrells","cite":"68 S.E. 337","y":1910,"court":"Ga. Ct. App.","url":"https://www.courtlistener.com/c/S.E./68/337/","by":{"3":"19"}},{"t":"usc","label":"18 U.S.C. § 1344","url":"https://www.law.cornell.edu/uscode/text/18/1344","by":{"3":"15"}},{"t":"case","label":"Atl. Delaine Co. v. James","cite":"94 U.S. 207","y":1876,"id":"scdb/1876-130","sc":1,"by":{"4":"8"},"q":[{"src":"brief","b":4,"text":"ought not to be exercised except in a clear case, and never … unless the complainant has been deceived and injured.","cite":"94 U.S. 207, 214"}]},{"t":"case","label":"California v. Texas","cite":"141 S. Ct. 2104","y":2021,"id":"2020/19-840","sc":1,"by":{"4":"4"}},{"t":"case","label":"Cutter v. Wilkinson","cite":"544 U.S. 709","y":2005,"id":"2004/03-9877","sc":1,"by":{"4":"4"}},{"t":"case","label":"Dunn v. United States","cite":"442 U.S. 100","y":1979,"id":"1978/77-6949","sc":1,"by":{"4":"5"},"q":[{"src":"argument","who":"Mr. Dreeben","text":"Well, Justice Barrett, the reason why I don't think that it's an appropriate issue for the Second Circuit to get on remand is this Court's repeated statements in cases like Dunn, McCormick, and specifically Chiarella and McNally itself that the Court cannot affirm a criminal conviction on the basis of a theory not presented to the jury."},{"src":"argument","who":"Mr. Feigin","text":"But we're not switching -- for the reasons I've been stating about what the assets at issue as to the right to control actually were, I think that there's no way to read this case as introducing the kind of new theory you had in Chiarella, where all of a sudden the victim of the fraud was different, or something like in Dunn, where the --"}]},{"t":"case","label":"Dura Pharms., Inc. v. Broudo","cite":"544 U.S. 336","y":2005,"id":"2004/03-932","sc":1,"by":{"4":"7"},"q":[{"src":"brief","b":4,"text":"that he suffered actual economic loss.","cite":"544 U.S. 336, 344"}]},{"t":"case","label":"Junius Constr. Corp. v. Cohen","cite":"257 N.Y. 393","y":1931,"url":"https://www.courtlistener.com/c/N.Y./257/393/","by":{"4":"17"},"q":[{"src":"brief","b":4,"text":"to the very essence of the bargain.","cite":"257 N.Y. 393, 400"}]},{"t":"case","label":"Mauro v. Raymark Indus., Inc.","cite":"561 A.2d 257","y":1989,"court":"N.J.","url":"https://www.courtlistener.com/c/A.2d/561/257/","by":{"4":"13"}},{"t":"case","label":"McCormick v. United States","cite":"500 U.S. 257","y":1991,"id":"1990/89-1918","sc":1,"by":{"4":"5"},"q":[{"src":"argument","who":"Mr. Dreeben","text":"Well, Justice Barrett, the reason why I don't think that it's an appropriate issue for the Second Circuit to get on remand is this Court's repeated statements in cases like Dunn, McCormick, and specifically Chiarella and McNally itself that the Court cannot affirm a criminal conviction on the basis of a theory not presented to the jury."}]},{"t":"case","label":"Niz-Chavez v. Garland","cite":"141 S. Ct. 1474","y":2021,"id":"2020/19-863","sc":1,"by":{"4":"5"},"q":[{"src":"brief","b":4,"text":"If men must turn square corners when they deal with the government, it cannot be too much to expect the government to turn square corners when it deals with them.","cite":"141 S. Ct. 1474, 1486"}]},{"t":"case","label":"OBB Personenverkehr AG v. Sachs","cite":"577 U.S. 27","y":2015,"id":"2015/13-1067","sc":1,"by":{"4":"4"}},{"t":"case","label":"One-O-One Enters. v. Caruso","cite":"848 F.2d 1283","y":1988,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/848/1283/","by":{"4":"19, 20"}},{"t":"case","label":"People v. Cook","cite":"8 N.Y. 67","y":1853,"url":"https://www.courtlistener.com/c/N.Y./8/67/","by":{"4":"7"}},{"t":"case","label":"S. Dev. Co. of Nev. v. Silva","cite":"125 U.S. 247","y":1888,"id":"scdb/1887-181","sc":1,"by":{"4":"8"}},{"t":"case","label":"Sonnesyn v. Akin","cite":"104 N.W. 1026","y":1905,"court":"N.D.","url":"https://www.courtlistener.com/c/N.W./104/1026/","by":{"4":"7"}},{"t":"case","label":"State v. Casperson","cite":"262 P. 294","y":1927,"court":"Utah","url":"https://www.courtlistener.com/c/P./262/294/","by":{"4":"9"}},{"t":"case","label":"State v. Palmer","cite":"32 P. 29","y":1893,"court":"Kan.","url":"https://www.courtlistener.com/c/P./32/29/","by":{"4":"9"}},{"t":"case","label":"Stirone v. United States","cite":"361 U.S. 212","y":1960,"id":"1959/35","sc":1,"by":{"4":"5"}},{"t":"case","label":"TransUnion LLC v. Ramirez","cite":"141 S. Ct. 2190","y":2021,"id":"2020/20-297","sc":1,"by":{"4":"13"}},{"t":"case","label":"United States v. Jones","cite":"565 U.S. 400","y":2012,"id":"2011/10-1259","sc":1,"by":{"4":"4"}},{"t":"case","label":"United States v. Lindsey","cite":"850 F.3d 1009","y":2017,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/850/1009/","by":{"4":"18"}},{"t":"case","label":"United States v. Palin","cite":"874 F.3d 418","y":2017,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/874/418/","by":{"4":"18"}},{"t":"case","label":"Va. Bankshares, Inc. v. Sandberg","cite":"501 U.S. 1083","y":1991,"id":"1990/89-1448","sc":1,"by":{"4":"19"}},{"t":"case","label":"Van Buren v. United States","cite":"141 S. Ct. 1648","y":2021,"id":"2020/19-783","sc":1,"by":{"4":"17"},"q":[{"src":"brief","b":4,"text":"cit[ing] any prior instance in which it has read the statute to contain","cite":"141 S. Ct. 1648, 1661"}]}]};